// Originally generated by `archegraph test`, now HAND-MAINTAINED. Edit freely.
//
// Promoted out of tests/testgen.test.ts, which every `archegraph test` run
// overwrites wholesale without asking -- one fixed path per package, not one
// per spec. These cover the COMMANDS registry, which is the surface every
// dispatcher (keymap, toolbar, context menu, palette) runs through, so they
// are worth more than the one pillar that happened to generate them.
//
// Companion to gestures/command_wiring.test.ts, which asks the narrower
// question "does every command DO anything at all". This file covers what
// the individual commands actually produce.
//
// Do NOT regenerate over this file. See 6b9f2b9.

import { describe, expect, test } from 'bun:test';
import { create } from '@bufbuild/protobuf';
import { CanvasStyleSchema, Glyph2DSchema, GroupLayoutSchema, GroupStyleEntrySchema, NodeLayoutSchema, NodeStyleEntrySchema, Stylesheet, StylesheetSchema, TypographySchema, Vec2, Vec2Schema } from '@archeglyph/proto/gen/style_pb';
import { StyleEdit } from '@archeglyph/proto/gen/style_pb';
import { LaidOutDiagram } from '@archeglyph/core/layout/laid_out_diagram';
import { SceneGeometry } from '../src/scene/scene';
import { COMMANDS, CommandContext, runCommand } from '../src/gestures/commands';
import { CommandId } from '../src/ui_state/keymap';
import { applyStyleEditToStylesheet } from '../src/state/apply_style_edit';
import { pinAllEdit, unpinAllEdit } from '../src/state/edits/layout_command';
import { EditorState } from '../src/state/editor_state';
import { UiState } from '../src/ui_state/ui_state';
import { ContainerRect } from '../src/ui_state/viewport_math';
import { LaidOutGroup } from '@archeglyph/core/layout/laid_out_group';
import { LaidOutNode } from '@archeglyph/core/layout/laid_out_node';


describe('testgen_gestures__COMMANDS', () => {
    // WHEN: pin-all fires when the Scene has a fully resolved LaidOutDiagram with multiple nodes; every node's current on-screen position is written into the stylesheet as an explicit position.
    // THEN: Returns a StyleEdit containing an explicit position for every node in the LaidOutDiagram, each set to that node's current on-screen coordinates.
    test('pin_all_with_resolved_layout_writes_current_positions', () => {
        function vec2(x: number, y: number): Vec2 { return create(Vec2Schema, { x, y }); }
          function laidOutNode(overrides: Partial<LaidOutNode> = {}): LaidOutNode {
            return { id: 'n1', parentGroup: undefined, position: vec2(0, 0), size: vec2(10, 10), shape: create(Glyph2DSchema, {}), typography: create(TypographySchema, {}), label: [], ...overrides } as LaidOutNode;
          }
          function laidOutDiagram(overrides: Partial<LaidOutDiagram> = {}): LaidOutDiagram {
            return { id: 'd1', canvas: create(CanvasStyleSchema, {}), nodes: [], edges: [], groups: [], annotations: [], ...overrides } as LaidOutDiagram;
          }
          function emptyStylesheet(overrides: Partial<Stylesheet> = {}): Stylesheet {
            return create(StylesheetSchema, { schemaVersion: 1, nodes: {}, edges: {}, groups: {}, annotations: {}, pendingEdits: [], ...overrides });
          }

          const sheet = emptyStylesheet();
          const n1 = laidOutNode({ id: 'n1', position: vec2(10, 20) });
          const n2 = laidOutNode({ id: 'n2', position: vec2(30, 40) });
          const diagram = laidOutDiagram({ nodes: [n1, n2] });
          const geometry = { diagram, index: [], byKey: {}, edgePolylines: {}, contentBounds: { minX: 0, minY: 0, maxX: 0, maxY: 0 }, svg: '' } as unknown as SceneGeometry;

          const edits: StyleEdit[] = [];
          const context: CommandContext = {
            state: { stylesheet: () => sheet, applyStyleEdit: (edit: StyleEdit) => { edits.push(edit); }, undo: () => {}, redo: () => {} } as unknown as EditorState,
            ui: { selection: () => [], setSelection: () => {} } as unknown as UiState,
            geometry,
            rect: {} as ContainerRect,
            save: () => {},
            beginTextEdit: () => {},
          };

          runCommand('pin-all' as unknown as CommandId, context);

          expect(edits).toHaveLength(1);
          const applied = applyStyleEditToStylesheet(sheet, edits[0]);
          expect(applied.nodes['n1'].layout?.position).toEqual(vec2(10, 20));
          expect(applied.nodes['n2'].layout?.position).toEqual(vec2(30, 40));
    });

    // WHEN: pin-all fires before the Scene has ever produced a LaidOutDiagram (geometry is absent/undefined) - a timing accident, not a user mistake - and the command must be a no-op rather than an error.
    // THEN: Returns a no-op StyleEdit (no position writes) since there is no geometry to pin.
    test('pin_all_before_first_layout_resolves_is_noop', () => {
        function emptyStylesheet(overrides: Partial<Stylesheet> = {}): Stylesheet {
            return create(StylesheetSchema, { schemaVersion: 1, nodes: {}, edges: {}, groups: {}, annotations: {}, pendingEdits: [], ...overrides });
          }

          const sheet = emptyStylesheet();
          const edits: StyleEdit[] = [];
          const context: CommandContext = {
            state: { stylesheet: () => sheet, applyStyleEdit: (edit: StyleEdit) => { edits.push(edit); }, undo: () => {}, redo: () => {} } as unknown as EditorState,
            ui: { selection: () => [], setSelection: () => {} } as unknown as UiState,
            geometry: undefined,
            rect: {} as ContainerRect,
            save: () => {},
            beginTextEdit: () => {},
          };

          expect(() => runCommand('pin-all' as unknown as CommandId, context)).not.toThrow();
          expect(edits).toHaveLength(0);
    });

    // WHEN: pin-all fires when the LaidOutDiagram exists but contains zero nodes; no position edits are produced.
    // THEN: Returns a StyleEdit with zero position entries, since there are no nodes to write positions for.
    test('pin_all_empty_diagram_produces_no_position_entries', () => {
        function laidOutDiagram(overrides: Partial<LaidOutDiagram> = {}): LaidOutDiagram {
            return { id: 'd1', canvas: create(CanvasStyleSchema, {}), nodes: [], edges: [], groups: [], annotations: [], ...overrides } as LaidOutDiagram;
          }
          function emptyStylesheet(overrides: Partial<Stylesheet> = {}): Stylesheet {
            return create(StylesheetSchema, { schemaVersion: 1, nodes: {}, edges: {}, groups: {}, annotations: {}, pendingEdits: [], ...overrides });
          }

          const sheet = emptyStylesheet();
          const diagram = laidOutDiagram();
          const geometry = { diagram, index: [], byKey: {}, edgePolylines: {}, contentBounds: { minX: 0, minY: 0, maxX: 0, maxY: 0 }, svg: '' } as unknown as SceneGeometry;

          const edits: StyleEdit[] = [];
          const context: CommandContext = {
            state: { stylesheet: () => sheet, applyStyleEdit: (edit: StyleEdit) => { edits.push(edit); }, undo: () => {}, redo: () => {} } as unknown as EditorState,
            ui: { selection: () => [], setSelection: () => {} } as unknown as UiState,
            geometry,
            rect: {} as ContainerRect,
            save: () => {},
            beginTextEdit: () => {},
          };

          runCommand('pin-all' as unknown as CommandId, context);

          expect(edits).toHaveLength(1);
          expect(edits[0].nodeChanges).toHaveLength(0);
          expect(edits[0].groupChanges).toHaveLength(0);
    });

    // WHEN: pin-all fires when the stylesheet already has explicit positions (e.g. from a prior pin-all or manual edit) for some nodes; those are overwritten with the current laid-out coordinates rather than left untouched or duplicated.
    // THEN: Returns a StyleEdit that sets each node's position entry to its current laid-out coordinates, overwriting any pre-existing explicit position for that node.
    test('pin_all_overwrites_existing_explicit_position', () => {
        function vec2(x: number, y: number): Vec2 { return create(Vec2Schema, { x, y }); }
          function laidOutNode(overrides: Partial<LaidOutNode> = {}): LaidOutNode {
            return { id: 'n1', parentGroup: undefined, position: vec2(0, 0), size: vec2(10, 10), shape: create(Glyph2DSchema, {}), typography: create(TypographySchema, {}), label: [], ...overrides } as LaidOutNode;
          }
          function laidOutDiagram(overrides: Partial<LaidOutDiagram> = {}): LaidOutDiagram {
            return { id: 'd1', canvas: create(CanvasStyleSchema, {}), nodes: [], edges: [], groups: [], annotations: [], ...overrides } as LaidOutDiagram;
          }

          const sheet = create(StylesheetSchema, {
            schemaVersion: 1,
            nodes: { n1: create(NodeStyleEntrySchema, { layout: create(NodeLayoutSchema, { position: vec2(1, 1) }) }) },
            edges: {}, groups: {}, annotations: {}, pendingEdits: [],
          });
          const diagram = laidOutDiagram({ nodes: [laidOutNode({ id: 'n1', position: vec2(100, 200) })] });
          const geometry = { diagram, index: [], byKey: {}, edgePolylines: {}, contentBounds: { minX: 0, minY: 0, maxX: 0, maxY: 0 }, svg: '' } as unknown as SceneGeometry;

          const edits: StyleEdit[] = [];
          const context: CommandContext = {
            state: { stylesheet: () => sheet, applyStyleEdit: (edit: StyleEdit) => { edits.push(edit); }, undo: () => {}, redo: () => {} } as unknown as EditorState,
            ui: { selection: () => [], setSelection: () => {} } as unknown as UiState,
            geometry,
            rect: {} as ContainerRect,
            save: () => {},
            beginTextEdit: () => {},
          };

          runCommand('pin-all' as unknown as CommandId, context);

          expect(edits).toHaveLength(1);
          expect(edits[0].nodeChanges).toHaveLength(1);
          const applied = applyStyleEditToStylesheet(sheet, edits[0]);
          expect(applied.nodes['n1'].layout?.position).toEqual(vec2(100, 200));
    });

    // WHEN: unpin-all fires when the stylesheet contains explicit positions written by multiple different origins at once (some from pin-all, some from drags, some from nudges, some hand-edited directly in the file); all of them are removed regardless of origin.
    // THEN: Returns a StyleEdit that removes every explicit position entry in the stylesheet regardless of which mechanism originally wrote it.
    test('unpin_all_removes_positions_regardless_of_origin', () => {
        function vec2(x: number, y: number): Vec2 { return create(Vec2Schema, { x, y }); }

          const sheet = create(StylesheetSchema, {
            schemaVersion: 1,
            nodes: {
              n1: create(NodeStyleEntrySchema, { layout: create(NodeLayoutSchema, { position: vec2(1, 1) }) }),
              n2: create(NodeStyleEntrySchema, { layout: create(NodeLayoutSchema, { position: vec2(2, 2) }) }),
              n3: create(NodeStyleEntrySchema, { layout: create(NodeLayoutSchema, { position: vec2(3, 3) }) }),
            },
            edges: {},
            groups: { g1: create(GroupStyleEntrySchema, { layout: create(GroupLayoutSchema, { position: vec2(4, 4) }) }) },
            annotations: {},
            pendingEdits: [],
          });

          const edits: StyleEdit[] = [];
          const context: CommandContext = {
            state: { stylesheet: () => sheet, applyStyleEdit: (edit: StyleEdit) => { edits.push(edit); }, undo: () => {}, redo: () => {} } as unknown as EditorState,
            ui: { selection: () => [], setSelection: () => {} } as unknown as UiState,
            geometry: undefined,
            rect: {} as ContainerRect,
            save: () => {},
            beginTextEdit: () => {},
          };

          runCommand('unpin-all' as unknown as CommandId, context);

          expect(edits).toHaveLength(1);
          const applied = applyStyleEditToStylesheet(sheet, edits[0]);
          expect(applied.nodes['n1'].layout?.position).toBeUndefined();
          expect(applied.nodes['n2'].layout?.position).toBeUndefined();
          expect(applied.nodes['n3'].layout?.position).toBeUndefined();
          expect(applied.groups['g1'].layout?.position).toBeUndefined();
    });

    // WHEN: unpin-all fires when the stylesheet already has no explicit positions anywhere (diagram already fully ELK-driven); the command is a no-op producing an edit with nothing to clear.
    // THEN: Returns a no-op StyleEdit, since there are no explicit positions to clear.
    test('unpin_all_with_no_explicit_positions_is_noop_shaped', () => {
        const sheet = create(StylesheetSchema, {
            schemaVersion: 1,
            nodes: { n1: create(NodeStyleEntrySchema, { component: 'plain' }) },
            edges: {}, groups: {}, annotations: {}, pendingEdits: [],
          });

          const edits: StyleEdit[] = [];
          const context: CommandContext = {
            state: { stylesheet: () => sheet, applyStyleEdit: (edit: StyleEdit) => { edits.push(edit); }, undo: () => {}, redo: () => {} } as unknown as EditorState,
            ui: { selection: () => [], setSelection: () => {} } as unknown as UiState,
            geometry: undefined,
            rect: {} as ContainerRect,
            save: () => {},
            beginTextEdit: () => {},
          };

          expect(() => runCommand('unpin-all' as unknown as CommandId, context)).not.toThrow();
          expect(edits).toHaveLength(1);
          const applied = applyStyleEditToStylesheet(sheet, edits[0]);
          expect(applied.nodes['n1'].layout?.position).toBeUndefined();
          expect(applied.nodes['n1'].component).toBe('plain');
    });

    // WHEN: unpin-all fires when the only explicit position present was added by directly hand-editing the stylesheet file (never touched by pin-all, drag, or nudge); it is still removed.
    // THEN: Returns a StyleEdit that removes the hand-edited explicit position just as it would remove one from any other origin.
    test('unpin_all_removes_hand_edited_single_position', () => {
        function vec2(x: number, y: number): Vec2 { return create(Vec2Schema, { x, y }); }

          const sheet = create(StylesheetSchema, {
            schemaVersion: 1,
            nodes: { n1: create(NodeStyleEntrySchema, { layout: create(NodeLayoutSchema, { position: vec2(9, 9) }), component: 'hand-edited' }) },
            edges: {}, groups: {}, annotations: {}, pendingEdits: [],
          });

          const edits: StyleEdit[] = [];
          const context: CommandContext = {
            state: { stylesheet: () => sheet, applyStyleEdit: (edit: StyleEdit) => { edits.push(edit); }, undo: () => {}, redo: () => {} } as unknown as EditorState,
            ui: { selection: () => [], setSelection: () => {} } as unknown as UiState,
            geometry: undefined,
            rect: {} as ContainerRect,
            save: () => {},
            beginTextEdit: () => {},
          };

          runCommand('unpin-all' as unknown as CommandId, context);

          expect(edits).toHaveLength(1);
          const applied = applyStyleEditToStylesheet(sheet, edits[0]);
          expect(applied.nodes['n1'].layout?.position).toBeUndefined();
          expect(applied.nodes['n1'].component).toBe('hand-edited');
    });


    // WHEN: auto-layout fires on a stylesheet that currently has explicit positions for all nodes; after the resulting edit is applied, the stylesheet has none, so the next scene computation is routed through ELK instead of using stored coordinates.
    // THEN: Returns a StyleEdit that clears all explicit positions, so the next scene computation runs through ELK instead of using stored coordinates.
    test('auto_layout_clears_all_positions_to_route_through_elk', () => {
        function vec2(x: number, y: number): Vec2 { return create(Vec2Schema, { x, y }); }

          const sheet = create(StylesheetSchema, {
            schemaVersion: 1,
            nodes: {
              n1: create(NodeStyleEntrySchema, { layout: create(NodeLayoutSchema, { position: vec2(5, 5) }) }),
              n2: create(NodeStyleEntrySchema, { layout: create(NodeLayoutSchema, { position: vec2(6, 6) }) }),
            },
            edges: {}, groups: {}, annotations: {}, pendingEdits: [],
          });

          const edits: StyleEdit[] = [];
          const context: CommandContext = {
            state: { stylesheet: () => sheet, applyStyleEdit: (edit: StyleEdit) => { edits.push(edit); }, undo: () => {}, redo: () => {} } as unknown as EditorState,
            ui: { selection: () => [], setSelection: () => {} } as unknown as UiState,
            geometry: undefined,
            rect: {} as ContainerRect,
            save: () => {},
            beginTextEdit: () => {},
          };

          runCommand('auto-layout' as unknown as CommandId, context);

          expect(edits).toHaveLength(1);
          const applied = applyStyleEditToStylesheet(sheet, edits[0]);
          expect(applied.nodes['n1'].layout?.position).toBeUndefined();
          expect(applied.nodes['n2'].layout?.position).toBeUndefined();
    });

    // WHEN: auto-layout fires when the stylesheet already has zero explicit positions; the command still runs (as the 're-run ELK' intent distinct from unpin-all's 'stop pinning' intent) and yields the same no-op-shaped edit as unpin-all would.
    // THEN: Returns the same no-op-shaped StyleEdit that unpin-all would produce, since there are no positions to clear but the command still runs as a distinct 're-run ELK' action.
    test('auto_layout_on_already_unpinned_stylesheet_still_runs', () => {
        const sheet = create(StylesheetSchema, {
            schemaVersion: 1,
            nodes: { n1: create(NodeStyleEntrySchema, { component: 'already-unpinned' }) },
            edges: {}, groups: {}, annotations: {}, pendingEdits: [],
          });

          const edits: StyleEdit[] = [];
          const context: CommandContext = {
            state: { stylesheet: () => sheet, applyStyleEdit: (edit: StyleEdit) => { edits.push(edit); }, undo: () => {}, redo: () => {} } as unknown as EditorState,
            ui: { selection: () => [], setSelection: () => {} } as unknown as UiState,
            geometry: undefined,
            rect: {} as ContainerRect,
            save: () => {},
            beginTextEdit: () => {},
          };

          runCommand('auto-layout' as unknown as CommandId, context);

          expect(edits).toHaveLength(1);
          const unpinAllOnSameShape = unpinAllEdit(sheet);
          // Compare everything except the wall-clock stamp. styleEdit() stamps
          // `timestampMs: BigInt(Date.now())`, and these are two separate calls
          // -- they are equal only when both land in the same millisecond, so
          // under load the assertion straddles one and fails by exactly 1ms.
          // Observed once here as 1789590334716n vs 1789590334715n.
          //
          // This is the SAME flake already repaired in auto_layout_edit.test.ts,
          // whose header documents it failing about one run in three. That repair
          // was promoted out; this copy was regenerated afterwards and brought the
          // defect back -- exactly the hazard archetest.yaml warns about, that a
          // repair left under a generated filename is one waiting to be reverted.
          const withoutTimestamp = (edit: StyleEdit): unknown => ({
            ...edit,
            timestampMs: undefined,
          });
          expect(withoutTimestamp(edits[0])).toEqual(withoutTimestamp(unpinAllOnSameShape));
    });

});

